    public static FfiConverterBoolean INSTANCE = new FfiConverterBoolean();

    public override bool Lift(sbyte value) {
        return value != 0;
    }

    public override bool Read(BigEndianStream stream) {
        return Lift(stream.ReadSByte());
    }

    public override sbyte Lower(bool value) {
        return value ? (sbyte)1 : (sbyte)0;
    }

    public override int AllocationSize(bool value) {
        return (sbyte)1;
    }

    public override void Write(bool value, BigEndianStream stream) {
        stream.WriteSByte(Lower(value));
    }
}



class FfiConverterString: FfiConverter<string, RustBuffer> {
    public static FfiConverterString INSTANCE = new FfiConverterString();

    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    public override string Lift(RustBuffer value) {
        try {
            var bytes = value.AsStream().ReadBytes(Convert.ToInt32(value.len));
            return System.Text.Encoding.UTF8.GetString(bytes);
        } finally {
            RustBuffer.Free(value);
        }
    }

    public override string Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        var bytes = stream.ReadBytes(length);
        return System.Text.Encoding.UTF8.GetString(bytes);
    }

    public override RustBuffer Lower(string value) {
        var bytes = System.Text.Encoding.UTF8.GetBytes(value);
        var rbuf = RustBuffer.Alloc(bytes.Length);
        rbuf.AsWriteableStream().WriteBytes(bytes);
        return rbuf;
    }

    // TODO(CS)
    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per unicode codepoint which will always be
    // enough.
    public override int AllocationSize(string value) {
        const int sizeForLength = 4;
        var sizeForString = System.Text.Encoding.UTF8.GetByteCount(value);
        return sizeForLength + sizeForString;
    }

    public override void Write(string value, BigEndianStream stream) {
        var bytes = System.Text.Encoding.UTF8.GetBytes(value);
        stream.WriteInt(bytes.Length);
        stream.WriteBytes(bytes);
    }
}




class FfiConverterByteArray: FfiConverterRustBuffer<byte[]> {
    public static FfiConverterByteArray INSTANCE = new FfiConverterByteArray();

    public override byte[] Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        return stream.ReadBytes(length);
    }

    public override int AllocationSize(byte[] value) {
        return 4 + value.Length;
    }

    public override void Write(byte[] value, BigEndianStream stream) {
        stream.WriteInt(value.Length);
        stream.WriteBytes(value);
    }
}



/// <summary>
/// Thread-safe TON Connect session exposed to Swift, Kotlin, and other hosts.
/// </summary>
internal interface ITonConnectSession {
    /// <summary>
    /// Approves the connect request and keeps its encrypted response pending delivery.
    ///
    /// Persist the session before posting the returned response. After the
    /// bridge accepts it, call [`Self::complete_pending_post`].
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectPreparedPost ApproveConnect(TonConnectAccountInfo @account, TonConnectProofReply? @proof, TonConnectDevice @device);
    /// <summary>
    /// Returns a complete SSE subscription URL and resets stream framing.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    string BeginEventsSubscription();
    /// <summary>
    /// Removes the pending response after the bridge accepts it.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    void CompletePendingPost();
    /// <summary>
    /// Returns the initial connect prompt while approval is pending.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectConnectPrompt? ConnectPrompt();
    /// <summary>
    /// Keeps a wallet-initiated disconnect event pending bridge delivery.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectPreparedPost Disconnect();
    /// <summary>
    /// Ingests an SSE chunk and returns only fresh authenticated requests.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectIncomingRequest[] IngestSseChunk(byte[] @chunk, ulong @now);
    /// <summary>
    /// Returns the exact response that must be retried before reading more events.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectPreparedPost? PendingPost();
    /// <summary>
    /// Returns restored requests that still await a wallet response.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectIncomingRequest[] PendingRequests(ulong @now);
    /// <summary>
    /// Serializes the secret-bearing session, requests, and pending response.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    string Persisted();
    /// <summary>
    /// Returns the current lifecycle phase.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectSessionPhase Phase();
    /// <summary>
    /// Keeps a successful dApp-initiated disconnect response pending delivery.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectPreparedPost PrepareDisconnectSuccess(string @requestId);
    /// <summary>
    /// Keeps a protocol RPC error pending delivery for the selected request.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectPreparedPost PrepareError(string @requestId, TonConnectRpcErrorCode @code, string @message);
    /// <summary>
    /// Keeps a successful `sendTransaction` response pending bridge delivery.
    ///
    /// The response contains the exact signed BOC returned to the dApp.
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectPreparedPost PrepareSendSuccess(string @requestId, string @signedBoc);
    /// <summary>
    /// Keeps a successful `signMessage` response pending bridge delivery.
    ///
    /// `internal_boc` must contain the complete signed internal message
    /// returned by [`crate::WalletClient::sign_message`].
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectPreparedPost PrepareSignMessageSuccess(string @requestId, string @internalBoc);
    /// <summary>
    /// Rejects the initial connection and keeps its terminal event pending delivery.
    ///
    /// Persist the session before posting the returned response. After the
    /// bridge accepts it, call [`Self::complete_pending_post`].
    /// </summary>
    /// <exception cref="TonConnectSessionException"></exception>
    TonConnectPreparedPost RejectConnect(string @message);
}
/// <summary>
/// Thread-safe TON Connect session exposed to Swift, Kotlin, and other hosts.
/// </summary>
internal class TonConnectSession : ITonConnectSession, IDisposable {
    protected ulong pointer;
    private int _wasDestroyed = 0;
    private long _callCounter = 1;

    public TonConnectSession(ulong pointer) {
        this.pointer = pointer;
    }

    ~TonConnectSession() {
        Destroy();
    }

    protected void FreeRustArcPtr() {
        _UniffiHelpers.RustCall((ref UniffiRustCallStatus status) => {
            _UniFFILib.uniffi_wallet_engine_fn_free_tonconnectsession(this.pointer, ref status);
        });
    }

    protected ulong CloneRustArcPtr() {
        return _UniffiHelpers.RustCall((ref UniffiRustCallStatus status) => {
            return _UniFFILib.uniffi_wallet_engine_fn_clone_tonconnectsession(this.pointer, ref status);
        });
    }

    public void Destroy()
    {
        // Only allow a single call to this method.
        if (Interlocked.CompareExchange(ref _wasDestroyed, 1, 0) == 0)
        {
            // This decrement always matches the initial count of 1 given at creation time.
            if (Interlocked.Decrement(ref _callCounter) == 0)
            {
                FreeRustArcPtr();
            }
        }
    }

    public void Dispose()
    {
        Destroy();
        GC.SuppressFinalize(this); // Suppress finalization to avoid unnecessary GC overhead.
    }

    private void IncrementCallCounter() 
    {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        long count;
        do
        {
            count = Interlocked.Read(ref _callCounter);
            if (count == 0L) throw new System.ObjectDisposedException(String.Format("'{0}' object has already been destroyed", this.GetType().Name));
            if (count == long.MaxValue) throw new System.OverflowException(String.Format("'{0}' call counter would overflow", this.GetType().Name));

        } while (Interlocked.CompareExchange(ref _callCounter, count + 1, count) != count);
    }

    private void DecrementCallCounter() 
    {
        // This decrement always matches the increment we performed above.
        if (Interlocked.Decrement(ref _callCounter) == 0) {
            FreeRustArcPtr();
        }
    }

    internal void CallWithPointer(Action<ulong> action)
    {
        IncrementCallCounter();
        try {
            action(CloneRustArcPtr());
        }
        finally {
            DecrementCallCounter();
        }
    }

    internal T CallWithPointer<T>(Func<ulong, T> func)
    {   
        IncrementCallCounter();
        try {
            return func(CloneRustArcPtr());
        }
        finally {
            DecrementCallCounter();
        }
    }

    
