class FfiConverterTypeWalletClient: FfiConverter<WalletClient, ulong> {
    public static FfiConverterTypeWalletClient INSTANCE = new FfiConverterTypeWalletClient();


    public override ulong Lower(WalletClient value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override WalletClient Lift(ulong value) {
        return new WalletClient(value);
    }

    public override WalletClient Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(WalletClient value) {
        return 8;
    }

    public override void Write(WalletClient value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



/// <summary>
/// Executes HTTP work for the engine.
///
/// The host must enforce the request timeout while it connects and reads the
/// response. It owns any local response limits, must reject redirects, and must
/// return the observed URL in `final_url`.
/// </summary>
internal interface IWalletHttpHost {
    /// <summary>
    /// Executes one complete HTTP request and returns an accepted response.
    ///
    /// The host can add its Toncenter credential according to the actual URL
    /// and its local security policy. It must return
    /// [`HttpHostErrorKind::Timeout`] when `request.timeout_ms` expires.
    /// </summary>
    /// <exception cref="HttpHostException"></exception>
    Task<HttpResponse> ExecuteHttp(HttpRequest @request);
    /// <summary>
    /// Requests cancellation of the request with `request_id`.
    ///
    /// This callback must be idempotent. It can run before `execute_http`
    /// registers the request, so the host must remember an early cancellation.
    /// </summary>
    Task CancelHttp(HttpRequestId @requestId);
}
/// <summary>
/// Executes HTTP work for the engine.
///
/// The host must enforce the request timeout while it connects and reads the
/// response. It owns any local response limits, must reject redirects, and must
/// return the observed URL in `final_url`.
/// </summary>
internal class WalletHttpHostImpl : IWalletHttpHost, IDisposable {
    protected ulong pointer;
    private int _wasDestroyed = 0;
    private long _callCounter = 1;

    public WalletHttpHostImpl(ulong pointer) {
        this.pointer = pointer;
    }

    ~WalletHttpHostImpl() {
        Destroy();
    }

    protected void FreeRustArcPtr() {
        _UniffiHelpers.RustCall((ref UniffiRustCallStatus status) => {
            _UniFFILib.uniffi_wallet_engine_fn_free_wallethttphost(this.pointer, ref status);
        });
    }

    protected ulong CloneRustArcPtr() {
        return _UniffiHelpers.RustCall((ref UniffiRustCallStatus status) => {
            return _UniFFILib.uniffi_wallet_engine_fn_clone_wallethttphost(this.pointer, ref status);
        });
    }

    public void Destroy()
    {
        // Only allow a single call to this method.
        if (Interlocked.CompareExchange(ref _wasDestroyed, 1, 0) == 0)
        {
            // This decrement always matches the initial count of 1 given at creation time.
            if (Interlocked.Decrement(ref _callCounter) == 0)
            {
                FreeRustArcPtr();
            }
        }
    }

    public void Dispose()
    {
        Destroy();
        GC.SuppressFinalize(this); // Suppress finalization to avoid unnecessary GC overhead.
    }

    private void IncrementCallCounter() 
    {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        long count;
        do
        {
            count = Interlocked.Read(ref _callCounter);
            if (count == 0L) throw new System.ObjectDisposedException(String.Format("'{0}' object has already been destroyed", this.GetType().Name));
            if (count == long.MaxValue) throw new System.OverflowException(String.Format("'{0}' call counter would overflow", this.GetType().Name));

        } while (Interlocked.CompareExchange(ref _callCounter, count + 1, count) != count);
    }

    private void DecrementCallCounter() 
    {
        // This decrement always matches the increment we performed above.
        if (Interlocked.Decrement(ref _callCounter) == 0) {
            FreeRustArcPtr();
        }
    }

    internal void CallWithPointer(Action<ulong> action)
    {
        IncrementCallCounter();
        try {
            action(CloneRustArcPtr());
        }
        finally {
            DecrementCallCounter();
        }
    }

    internal T CallWithPointer<T>(Func<ulong, T> func)
    {   
        IncrementCallCounter();
        try {
            return func(CloneRustArcPtr());
        }
        finally {
            DecrementCallCounter();
        }
    }

    
