/// <summary>
/// A bounded summary of the Toncenter trace emulated before authorization.
/// </summary>
/// <param name="McBlockSeqno">
/// The masterchain block used as the emulation state snapshot.
/// </param>
/// <param name="WalletFeesNanograms">
/// Fees charged by the source wallet transaction, in nanograms.
/// </param>
/// <param name="TraceFeesNanograms">
/// Sum of fees across every transaction currently present in the trace.
/// </param>
/// <param name="TransactionCount">
/// Number of transactions currently present in the emulated trace.
/// </param>
/// <param name="Actions">
/// High-level actions recognized by Toncenter in the emulated trace.
/// </param>
/// <param name="Transactions">
/// Per-account transaction outcomes observed before optional action parsing.
/// 
/// This evidence lets typed contract flows validate execution even when a
/// Toncenter deployment does not recognize the corresponding high-level action.
/// </param>
/// <param name="TraceSucceeded">
/// Whether every returned transaction completed without an observed phase failure.
/// 
/// A false value does not by itself block submission. A recipient can
/// reject or bounce after the source wallet transaction succeeds.
/// </param>
/// <param name="IsIncomplete">
/// Whether Toncenter reports that the trace still has unresolved messages.
/// </param>
internal record SendEmulation (
    /// <summary>
    /// The masterchain block used as the emulation state snapshot.
    /// </summary>
    uint McBlockSeqno, 
    /// <summary>
    /// Fees charged by the source wallet transaction, in nanograms.
    /// </summary>
    UnsignedDecimalString WalletFeesNanograms, 
    /// <summary>
    /// Sum of fees across every transaction currently present in the trace.
    /// </summary>
    UnsignedDecimalString TraceFeesNanograms, 
    /// <summary>
    /// Number of transactions currently present in the emulated trace.
    /// </summary>
    ulong TransactionCount, 
    /// <summary>
    /// High-level actions recognized by Toncenter in the emulated trace.
    /// </summary>
    SendEmulationAction[] Actions, 
    /// <summary>
    /// Per-account transaction outcomes observed before optional action parsing.
    ///
    /// This evidence lets typed contract flows validate execution even when a
    /// Toncenter deployment does not recognize the corresponding high-level action.
    /// </summary>
    SendEmulationTransaction[] Transactions, 
    /// <summary>
    /// Whether every returned transaction completed without an observed phase failure.
    ///
    /// A false value does not by itself block submission. A recipient can
    /// reject or bounce after the source wallet transaction succeeds.
    /// </summary>
    bool TraceSucceeded, 
    /// <summary>
    /// Whether Toncenter reports that the trace still has unresolved messages.
    /// </summary>
    bool IsIncomplete
) {
}

class FfiConverterTypeSendEmulation: FfiConverterRustBuffer<SendEmulation> {
    public static FfiConverterTypeSendEmulation INSTANCE = new FfiConverterTypeSendEmulation();

    public override SendEmulation Read(BigEndianStream stream) {
        return new SendEmulation(
            McBlockSeqno: FfiConverterUInt32.INSTANCE.Read(stream),
            WalletFeesNanograms: FfiConverterTypeUnsignedDecimalString.INSTANCE.Read(stream),
            TraceFeesNanograms: FfiConverterTypeUnsignedDecimalString.INSTANCE.Read(stream),
            TransactionCount: FfiConverterUInt64.INSTANCE.Read(stream),
            Actions: FfiConverterSequenceTypeSendEmulationAction.INSTANCE.Read(stream),
            Transactions: FfiConverterSequenceTypeSendEmulationTransaction.INSTANCE.Read(stream),
            TraceSucceeded: FfiConverterBoolean.INSTANCE.Read(stream),
