            + FfiConverterTypeUnsignedDecimalString.INSTANCE.AllocationSize(value.WalletFeesNanograms)
            + FfiConverterTypeUnsignedDecimalString.INSTANCE.AllocationSize(value.TraceFeesNanograms)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.TransactionCount)
