/// <summary>
/// An HTTP failure returned by [`WalletHttpHost`].
/// </summary>
internal class HttpHostException: UniffiException {
    HttpHostException() : base() {}
    HttpHostException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// Reports a classified host failure with a safe diagnostic message.
    /// </summary>
    
    public class Failed : HttpHostException {
        // Members
        public HttpHostErrorKind @kind;
        public string @diagnostic;

        // Constructor
        public Failed(
                HttpHostErrorKind @kind, 
                string @diagnostic) : base(
                "@kind" + "=" + @kind+ ", " +
                "@diagnostic" + "=" + @diagnostic) {

            this.@kind = @kind;

            this.@diagnostic = @diagnostic;
        }
    }
    

    
    public override string ToString() {
        return FfiConverterString.INSTANCE.Lift(
    _UniffiHelpers.RustCall( (ref UniffiRustCallStatus _status) =>
    _UniFFILib.uniffi_wallet_engine_fn_method_httphosterror_uniffi_trait_display(FfiConverterTypeHttpHostError.INSTANCE.Lower(this),  ref _status)
));
    }
}

class FfiConverterTypeHttpHostError : FfiConverterRustBuffer<HttpHostException>, CallStatusErrorHandler<HttpHostException> {
    public static FfiConverterTypeHttpHostError INSTANCE = new FfiConverterTypeHttpHostError();

    public override HttpHostException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new HttpHostException.Failed(
                    FfiConverterTypeHttpHostErrorKind.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeHttpHostError.Read()", value));
        }
    }

    public override int AllocationSize(HttpHostException value) {
        switch (value) {

            case HttpHostException.Failed variant_value:
                return 4
                    + FfiConverterTypeHttpHostErrorKind.INSTANCE.AllocationSize(variant_value.@kind)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@diagnostic);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeHttpHostError.AllocationSize()", value));
        }
    }

    public override void Write(HttpHostException value, BigEndianStream stream) {
        switch (value) {
            case HttpHostException.Failed variant_value:
                stream.WriteInt(1);
                FfiConverterTypeHttpHostErrorKind.INSTANCE.Write(variant_value.@kind, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@diagnostic, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeHttpHostError.Write()", value));
        }
    }
}





