/// <summary>
/// A wallet creation, import, secret, or derivation failure.
/// </summary>
internal class WalletLifecycleException: UniffiException {
    WalletLifecycleException() : base() {}
    WalletLifecycleException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
