    /// </summary>
    public class AddressDerivationFailed : WalletLifecycleException {
        public AddressDerivationFailed() : base() {}
    }
    
    
    /// <summary>
    /// The TON Connect proof fields or signing key are invalid.
    /// </summary>
    public class TonConnectSigningFailed : WalletLifecycleException {
        public TonConnectSigningFailed() : base() {}
    }
    
    
    /// <summary>
    /// The protected mnemonic derives a different address from the descriptor.
    /// </summary>
    public class SecretWalletMismatch : WalletLifecycleException {
        public SecretWalletMismatch() : base() {}
    }
    
    
    /// <summary>
    /// The host reported a protected-storage failure.
    /// </summary>
    
    public class ProtectedSecretHost : WalletLifecycleException {
        // Members
        public ProtectedSecretHostErrorKind @kind;
        public string @diagnostic;

        // Constructor
