        switch (value) {
            case 1: return WalletOperationOutcome.Completed;
            case 2: return WalletOperationOutcome.PartiallyCompleted;
            case 3: return WalletOperationOutcome.Failed;
            case 4: return WalletOperationOutcome.Cancelled;
            case 5: return WalletOperationOutcome.Superseded;
            case 6: return WalletOperationOutcome.Skipped;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeWalletOperationOutcome.Read()", value));
        }
    }

    public override int AllocationSize(WalletOperationOutcome value) {
        return 4;
    }

    public override void Write(WalletOperationOutcome value, BigEndianStream stream) {
        switch (value) {
            case WalletOperationOutcome.Completed: stream.WriteInt(1); break;
            case WalletOperationOutcome.PartiallyCompleted: stream.WriteInt(2); break;
            case WalletOperationOutcome.Failed: stream.WriteInt(3); break;
            case WalletOperationOutcome.Cancelled: stream.WriteInt(4); break;
            case WalletOperationOutcome.Superseded: stream.WriteInt(5); break;
            case WalletOperationOutcome.Skipped: stream.WriteInt(6); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeWalletOperationOutcome.Write()", value));
        }
    }
